/* Klaviyo and Omnisend connected (Settings > Integrations): a store's private key kept sealed in commerce_integrations (provider klaviyo or omnisend, category marketing), the marketing_sync job on the commerce job queue, and marketing_sync_items, the record of what was sent to each (a subscriber's state, an order event, an unsubscribe read back) so nothing goes twice and the integration card can count it. The three checks are rebuilt with every value they already allow plus the new ones, read from the database (as ARRAY['a'::text] or as '{a,b}'), so a part run before or after this one that added its own values keeps them; rebuilt NOT VALID, no row is read again. No rows change. Server only. Needs part 78; without it the first three lines say so and change nothing. Until it runs, connecting says it needs this part and the onsite scripts work as before. Safe to run again. */
DO $do$ DECLARE v text[]; BEGIN IF to_regclass('public.commerce_jobs') IS NULL THEN RAISE NOTICE 'commerce_jobs is not there yet: run part 78 first'; RETURN; END IF; SELECT coalesce(array_agg(DISTINCT m[1]), '{}'::text[]) INTO v FROM pg_constraint c CROSS JOIN LATERAL regexp_matches(pg_get_constraintdef(c.oid), '[''{,]([a-z][a-z0-9_]*)(?=['',}])', 'g') AS m WHERE c.conrelid = 'public.commerce_jobs'::regclass AND c.conname = 'commerce_jobs_kind_check'; v := ARRAY(SELECT DISTINCT x FROM unnest(v || ARRAY['forward_fulfillment', 'supplier_email', 'webhook_delivery', 'tracking_sync', 'inventory_sync', 'send_email', 'marketing_sync']) AS x ORDER BY x); ALTER TABLE public.commerce_jobs DROP CONSTRAINT IF EXISTS commerce_jobs_kind_check; EXECUTE format('ALTER TABLE public.commerce_jobs ADD CONSTRAINT commerce_jobs_kind_check CHECK (kind = ANY (%L::text[])) NOT VALID', v); END $do$;
DO $do$ DECLARE v text[]; BEGIN IF to_regclass('public.commerce_integrations') IS NULL THEN RAISE NOTICE 'commerce_integrations is not there yet: run part 78 first'; RETURN; END IF; SELECT coalesce(array_agg(DISTINCT m[1]), '{}'::text[]) INTO v FROM pg_constraint c CROSS JOIN LATERAL regexp_matches(pg_get_constraintdef(c.oid), '[''{,]([a-z][a-z0-9_]*)(?=['',}])', 'g') AS m WHERE c.conrelid = 'public.commerce_integrations'::regclass AND c.conname = 'commerce_integrations_provider_check'; v := ARRAY(SELECT DISTINCT x FROM unnest(v || ARRAY['manual', 'supplier_email', 'custom_webhook', 'csv', 'printful', 'printify', 'gelato', 'cj_dropshipping', 'shipstation', 'shippo', 'easypost', 'klaviyo', 'omnisend']) AS x ORDER BY x); ALTER TABLE public.commerce_integrations DROP CONSTRAINT IF EXISTS commerce_integrations_provider_check; EXECUTE format('ALTER TABLE public.commerce_integrations ADD CONSTRAINT commerce_integrations_provider_check CHECK (provider = ANY (%L::text[])) NOT VALID', v); END $do$;
DO $do$ DECLARE v text[]; BEGIN IF to_regclass('public.commerce_integrations') IS NULL THEN RAISE NOTICE 'commerce_integrations is not there yet: run part 78 first'; RETURN; END IF; SELECT coalesce(array_agg(DISTINCT m[1]), '{}'::text[]) INTO v FROM pg_constraint c CROSS JOIN LATERAL regexp_matches(pg_get_constraintdef(c.oid), '[''{,]([a-z][a-z0-9_]*)(?=['',}])', 'g') AS m WHERE c.conrelid = 'public.commerce_integrations'::regclass AND c.conname = 'commerce_integrations_category_check'; v := ARRAY(SELECT DISTINCT x FROM unnest(v || ARRAY['fulfillment', 'print_on_demand', 'dropshipping', 'supplier', 'shipping', 'marketing']) AS x ORDER BY x); ALTER TABLE public.commerce_integrations DROP CONSTRAINT IF EXISTS commerce_integrations_category_check; EXECUTE format('ALTER TABLE public.commerce_integrations ADD CONSTRAINT commerce_integrations_category_check CHECK (category = ANY (%L::text[])) NOT VALID', v); END $do$;
CREATE TABLE IF NOT EXISTS public.marketing_sync_items (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, provider text NOT NULL CHECK (provider IN ('klaviyo', 'omnisend')), item_key text NOT NULL CHECK (char_length(item_key) BETWEEN 1 AND 200), state text NOT NULL CHECK (state IN ('subscribed', 'unsubscribed', 'customer', 'sent', 'line', 'pulled')), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (creator_id, provider, item_key));
CREATE INDEX IF NOT EXISTS marketing_sync_items_state_idx ON public.marketing_sync_items (creator_id, provider, state);
ALTER TABLE public.marketing_sync_items ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.marketing_sync_items FROM anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.marketing_sync_items TO service_role;
notify pgrst, 'reload schema';
